{"content": "class Controller:
    def __init__(self):
        self.generation = 0
        self.rows = []
        self.decisions = {}
        self.busy = False
        self._polled_generations = set()
        self._finished_generations = set()

    def start(self):
        self.generation += 1
        self.busy = True
        return self.generation

    def poll_status(self, generation, status):
        # Stale if generation doesn't match current
        if generation != self.generation:
            return False

        # Duplicate if already returned True for this generation
        if generation in self._polled_generations:
            return False

        if status == "completed":
            # Only the latest running generation transitioning to completed returns True ONCE
            self._polled_generations.add(generation)
            return True
        elif status in ("queued", "running"):
            # queued/running keep busy
            return False
        elif status == "failed":
            # failed ends busy without fetching
            self.busy = False
            return False
        else:
            # Stale/duplicate statuses return False
            return False

    def finish(self, generation, rows):
        # Stale/unrequested finish returns False
        if generation != self.generation:
            return False

        # Only accept latest completed pending results once
        if generation in self._finished_generations:
            return False

        # Copy rows
        self.rows = list(rows)

        # End busy
        self.busy = False

        self._finished_generations.add(generation)
        return True

    def set_decision(self, job_id, value):
        self.decisions[job_id] = value"}
